fn is_happy(s: Vec<char>) -> bool {
    let n = s.len();
    // Must have at least three characters
    if n < 3 {
        return false;
    }
    // Check every consecutive window of length 3 for pairwise distinctness
    for window in s.windows(3) {
        if window[0] == window[1] 
            || window[0] == window[2] 
            || window[1] == window[2] 
        {
            return false;
        }
    }
    true
}

#[cfg(test)]
mod tests {
    use super::is_happy;

    #[test]
    fn test_too_short() {
        assert!(!is_happy(vec![]));
        assert!(!is_happy(vec!['a']));
        assert!(!is_happy(vec!['a', 'b']));
    }

    #[test]
    fn test_exactly_three() {
        assert!(is_happy(vec!['a', 'b', 'c']));
        assert!(!is_happy(vec!['a', 'b', 'a']));
    }

    #[test]
    fn test_longer_sequences() {
        assert!(is_happy(vec!['x', 'y', 'z', 'a', 'b']));
        assert!(!is_happy(vec!['x', 'y', 'y', 'z']));
        assert!(!is_happy(vec!['p', 'q', 'r', 'p', 'q'])); // "r","p","q" is okay but "p","q","q" fails
    }
}